// Copy-paste compact PE+stream packaging. Default PE=16 SIMD=4 for autosa_mm. For 32x8: PE_NUM=32 SIMD=8 ap_uint<256> pack8, pe_kj=512, wrap DATAFLOW.
// Keep autosa_mm(A[I][K], B[J][K], C[I][J]). Do not emit AutoSA kernel0 / A_t16 netlist.
// When I/PE_NUM>1 (getting_started/intel): wrap DATAFLOW with pe_i0 in the TOP. Do not loop tiles inside mm_pe.
// CRITICAL: stream type MUST be packed ap_uint (128 for 16x4, 256 for 32x8). struct-of-floats serializes to II=4.
// CRITICAL: do not complete-partition Crow. That muxes Crow[j] into mux_case_0 → II=4 FP-add.
// CRITICAL: flatten k×j into ONE pe_kj pipeline of 1024 beats. Do not use LOOP_FLATTEN off.
// Do not DEPENDENCE inter false: Crow[j] reuse distance is J=64; ram_2p allows II=1.
#include "kernel.h"
#include <hls_stream.h>
#include <ap_int.h>

#define PE_NUM 16
#define SIMD 4
typedef ap_uint<128> vec4_bits;

static vec4_bits pack4(data_t v0, data_t v1, data_t v2, data_t v3) {
#pragma HLS INLINE
  union { unsigned u; float f; } c0, c1, c2, c3;
  c0.f = (float)v0; c1.f = (float)v1; c2.f = (float)v2; c3.f = (float)v3;
  return (ap_uint<32>(c3.u), ap_uint<32>(c2.u), ap_uint<32>(c1.u), ap_uint<32>(c0.u));
}

static void unpack4(vec4_bits w, data_t &v0, data_t &v1, data_t &v2, data_t &v3) {
#pragma HLS INLINE
  union { unsigned u; float f; } c0, c1, c2, c3;
  c0.u = (unsigned)w(31, 0);
  c1.u = (unsigned)w(63, 32);
  c2.u = (unsigned)w(95, 64);
  c3.u = (unsigned)w(127, 96);
  v0 = (data_t)c0.f; v1 = (data_t)c1.f; v2 = (data_t)c2.f; v3 = (data_t)c3.f;
}

static void load_A(data_t A[I][K], hls::stream<vec4_bits> fifo_A[PE_NUM]) {
#pragma HLS INLINE off
  load_i0: for (int i0 = 0; i0 < I; i0 += PE_NUM) {
    load_k0: for (int k0 = 0; k0 < K; k0 += SIMD) {
      load_p: for (int p = 0; p < PE_NUM; ++p) {
#pragma HLS PIPELINE II=1
        fifo_A[p].write(pack4(A[i0 + p][k0 + 0], A[i0 + p][k0 + 1], A[i0 + p][k0 + 2], A[i0 + p][k0 + 3]));
      }
    }
  }
}

static void load_B(data_t B[J][K], hls::stream<vec4_bits> &fifo_B) {
#pragma HLS INLINE off
  load_i0: for (int i0 = 0; i0 < I; i0 += PE_NUM) {
    load_k0: for (int k0 = 0; k0 < K; k0 += SIMD) {
      load_j: for (int j = 0; j < J; ++j) {
#pragma HLS PIPELINE II=1
        fifo_B.write(pack4(B[j][k0 + 0], B[j][k0 + 1], B[j][k0 + 2], B[j][k0 + 3]));
      }
    }
  }
}

static void mm_pe(
    hls::stream<vec4_bits> &fifo_A,
    hls::stream<vec4_bits> &fifo_B_in,
    hls::stream<vec4_bits> &fifo_B_out,
    hls::stream<data_t> &fifo_C) {
#pragma HLS INLINE off
  data_t Crow[J];
#pragma HLS BIND_STORAGE variable=Crow type=ram_2p impl=bram
  pe_i0: for (int i0 = 0; i0 < I; i0 += PE_NUM) {
    // Do not flatten pe_i0: Crow holds one output row.
    data_t a0, a1, a2, a3;
    pe_kj: for (int t = 0; t < (K / SIMD) * J; ++t) {
#pragma HLS PIPELINE II=1
      const int k_tile = t / J;
      const int j = t - k_tile * J;
      if (j == 0) {
        unpack4(fifo_A.read(), a0, a1, a2, a3);
      }
      vec4_bits bw = fifo_B_in.read();
      fifo_B_out.write(bw);
      data_t b0, b1, b2, b3;
      unpack4(bw, b0, b1, b2, b3);
      data_t partial = a0 * b0 + a1 * b1 + a2 * b2 + a3 * b3;
      data_t acc = (k_tile == 0) ? partial : (Crow[j] + partial);
      Crow[j] = acc;
      if (k_tile == (K / SIMD) - 1) {
        fifo_C.write(acc);
      }
    }
  }
}

static void drain_B(hls::stream<vec4_bits> &fifo_B) {
#pragma HLS INLINE off
  drain_i0: for (int i0 = 0; i0 < I; i0 += PE_NUM) {
    drain_k0: for (int k0 = 0; k0 < K; k0 += SIMD) {
      drain_j: for (int j = 0; j < J; ++j) {
#pragma HLS PIPELINE II=1
        (void)fifo_B.read();
      }
    }
  }
}

static void store_C(data_t C[I][J], hls::stream<data_t> fifo_C[PE_NUM]) {
#pragma HLS INLINE off
  store_i0: for (int i0 = 0; i0 < I; i0 += PE_NUM) {
    store_p: for (int p = 0; p < PE_NUM; ++p) {
      store_j: for (int j = 0; j < J; ++j) {
#pragma HLS PIPELINE II=1
        C[i0 + p][j] = fifo_C[p].read();
      }
    }
  }
}

// Top: keep INTERFACE pragmas, then streams + DATAFLOW + 16 mm_pe() calls.
// Name the PE function mm_pe (NOT PE).
// hls::stream<vec4_bits> fifo_A[PE_NUM];
// hls::stream<vec4_bits> fifo_B[PE_NUM + 1];
// hls::stream<data_t> fifo_C[PE_NUM];
// #pragma HLS DATAFLOW

// DRAM loaders pack 4 floats into ap_uint<128> then write one stream beat.
load_A(A, fifo_A);
load_B(B, fifo_B[0]);
store_C(C, fifo_C);

mm_pe(fifo_A[0],  fifo_B[0],  fifo_B[1],  fifo_C[0]);
mm_pe(fifo_A[1],  fifo_B[1],  fifo_B[2],  fifo_C[1]);
// ... 16 explicit mm_pe calls ...
mm_pe(fifo_A[15], fifo_B[15], fifo_B[16], fifo_C[15]);
drain_B(fifo_B[16]);

// BAD: complete-partition Crow on the pipelined J index.
// HLS muxes Crow[j] into mux_case_0; false carried FP-add dep → II=4, DSP=5/PE.
data_t Crow[J];
#pragma HLS ARRAY_PARTITION variable=Crow complete  // DO NOT DO THIS
// BAD: LOOP_FLATTEN off on nested pe_k0/compute_j.
// Restarts a depth-35 pipeline 16 times → ~7070 cycles vs rank1 4228.
// GOOD: ram_2p Crow; one pe_kj of 1024 beats; fuse init/drain; do not DEPENDENCE inter false.
// Also BAD: struct-of-floats SIMD FIFOs; DATAFLOW on DSE LCST; AutoSA kernel0; function named PE if #define PE.

// Integer SIMD pack (uint16 SIMD=2 -> ap_uint<32>). Do not use float union.
static ap_uint<32> pack2_u16(data_t v0, data_t v1) {
#pragma HLS INLINE
  ap_uint<32> w = 0;
  w.range(15, 0) = (unsigned short)v0;
  w.range(31, 16) = (unsigned short)v1;
  return w;
}
// uint32 SIMD=4 -> ap_uint<128> from four unsigned ints (raw bits).
// float SIMD=4 stays ap_uint<128> with the existing pack4.
// float SIMD=8 (32x8 overlay) -> ap_uint<256> pack8 of eight floats.
// Top: #define PE_NUM 32  (or 16 / 8 from recipe)
// mm_pe(fifo_A[0], fifo_B[0], fifo_B[1], fifo_C[0]); ... through PE_NUM-1

// I/PE_NUM=2: wrap DATAFLOW. Tasks see ONE tile (pe_kj=1024). Depth>=8 ping-pong.
// BAD: for (tile < ROWS_PER_PE) inside mm_pe/load_B → 2048 beats / firing → ~4307 cycles.
extern "C" void autosa_mm_getting_started(data_t A[I][K], data_t B[J][K], data_t C[I][J]) {
  // keep existing INTERFACE pragmas
  hls::stream<ap_uint<128> > fifo_A[PE_NUM];
  hls::stream<ap_uint<128> > fifo_B[PE_NUM + 1];
  hls::stream<data_t> fifo_C[PE_NUM];
#pragma HLS STREAM variable=fifo_A depth=16
#pragma HLS STREAM variable=fifo_B depth=8
#pragma HLS STREAM variable=fifo_C depth=64
#pragma HLS ARRAY_PARTITION variable=fifo_A complete
#pragma HLS ARRAY_PARTITION variable=fifo_B complete
#pragma HLS ARRAY_PARTITION variable=fifo_C complete
  tile_i0: for (int i0 = 0; i0 < I; i0 += PE_NUM) {
#pragma HLS DATAFLOW
    load_A(A, fifo_A, i0);          // rows i0..i0+31 only; no tile loop inside
    load_B(B, fifo_B[0]);           // one pe_kj=1024, no i0 loop
    mm_pe(fifo_A[0], fifo_B[0], fifo_B[1], fifo_C[0]); // 32 explicit calls; pe_kj only
    drain_B(fifo_B[PE_NUM]);
    store_C(C, fifo_C, i0);
  }
}
// mm_pe: Crow ram_2p; pe_kj of (K/SIMD)*J; NO for (tile) / NO i0 += PE_NUM.
